const { withAppBuildGradle } = require('expo/config-plugins');
const { applyReleaseSigning } = require('./release-signing');

/**
 * Teaches the generated Android project how to sign release builds.
 *
 * Why this exists: `android/` is generated by `expo prebuild` and is git-ignored,
 * so any signing config edited into `android/app/build.gradle` by hand is erased
 * the next time it regenerates — and the build silently falls back to the debug
 * key, producing an APK that cannot be installed as an update over the real one.
 * Expressing it as a config plugin makes the signing setup part of the project
 * definition instead of a manual step someone has to remember.
 *
 * The key itself never appears here. Gradle reads it at build time from
 * `keystore.properties` at the project root, which is git-ignored along with the
 * keystore. This file is safe to commit; those two are not.
 *
 * If `keystore.properties` is absent the injected Groovy guard makes the config
 * inert, so `prebuild` and debug builds keep working on a fresh clone with no
 * key set up.
 *
 * The transformation itself lives in ./release-signing.js so it can be unit
 * tested — see tests/plugins/release-signing.test.ts for why that matters.
 */
function withReleaseSigning(config) {
  return withAppBuildGradle(config, (modConfig) => {
    // Groovy only. A Kotlin-DSL build file needs different syntax, and silently
    // doing nothing would hand back a debug-signed release.
    if (modConfig.modResults.language !== 'groovy') {
      throw new Error(
        `with-release-signing expects a Groovy build.gradle, got "${modConfig.modResults.language}".`
      );
    }

    modConfig.modResults.contents = applyReleaseSigning(modConfig.modResults.contents);
    return modConfig;
  });
}

module.exports = withReleaseSigning;
